"""Independent FK/native-GT scoring from recovered rig quaternions; no fitted spatial alignment."""
from pathlib import Path
import argparse,json,numpy as np
from scipy.spatial.transform import Rotation
ap=argparse.ArgumentParser();ap.add_argument('--project',required=True);ap.add_argument('--motion',required=True);ap.add_argument('--out',required=True);ap.add_argument('--gt',default='',help='Explicit ground-truth NPZ for another known-camera project; never inferred from a shared rig')
a=ap.parse_args();P=Path(a.project);cfg=json.loads((P/'creature.json').read_text());rigdir=(P/cfg.get('rig','rig')).resolve();d=np.load(a.motion);info=json.loads((rigdir/'rig.json').read_text());bones=info['bones'];names=[b['name'] for b in bones];rest=np.array([b['rest'] for b in bones]);parents=np.array([-1 if b['parent'] is None else names.index(b['parent']) for b in bones]);rl=np.array([np.linalg.inv(rest[parents[j]])@rest[j] if parents[j]>=0 else rest[j] for j in range(len(names))]);arm=np.array(info['armature_world']);root=str(d['root']);order=[names.index(str(n)) for n in d['bones']]
start=np.array([info['start_pose'].get(n,np.eye(4)) for n in names]);scale=np.linalg.norm(start[:,:3,:3],axis=1);world=[];minimum=[];skin_samples=[];skin_indices=set(np.linspace(0,len(d['times'])-1,min(9,len(d['times'])),dtype=int).tolist())
mesh=np.load(rigdir/'mesh.npz');restv=mesh['verts'];idx=mesh['idx'];wts=mesh['wts'];ib=np.linalg.inv(rest)
for frame_index,(quats,loc) in enumerate(zip(d['quaternions'],d['root_location'])):
 basis=start.copy();basis[order,:3,:3]=Rotation.from_quat(np.asarray(quats)[:,[1,2,3,0]]).as_matrix()*scale[order,None,:];basis[names.index(root),:3,3]=loc
 G=np.zeros_like(rest)
 for j in range(len(names)):G[j]=(G[parents[j]] if parents[j]>=0 else np.eye(4))@rl[j]@basis[j]
 GW=arm@G;world.append(GW[:,:3,3]);skin=G@ib;T=skin[idx];v=np.sum(wts[:,:,None]*(np.einsum('nvij,nvj->nvi',T[...,:3,:3],np.broadcast_to(restv[:,None,:],(len(restv),4,3)))+T[...,:3,3]),axis=1);v=v@arm[:3,:3].T+arm[:3,3];minimum.append(float(v[:,2].min()))
 if frame_index in skin_indices:skin_samples.append(v.copy())
world=np.array(world);t=np.array(d['times']);report={'motion':Path(a.motion).name,'frames':len(t),'first_time_s':float(t[0]),'last_time_s':float(t[-1]),'nominal_duration_s':float(t[-1]+np.median(np.diff(t))) if len(t)>1 else 0,'root_bone':root,'bones':len(names),'finite':bool(np.isfinite(world).all()),'minimum_skin_floor_clearance_m':min(minimum),'floor_clearance_percentiles_m':np.percentile(minimum,[0,5,50,95,100]).tolist(),'spatial_alignment_applied':False,'time_alignment_applied':False}
cfg=json.loads((P/'creature.json').read_text());stem=Path(a.motion).stem;base=next((n for n in cfg.get('clips',{})if stem==n or stem.startswith(n+'-')),stem);camfile=P/'work'/base/'cameras-aligned.json'
if camfile.exists():report['solver_frame0_camera_adjustment']=json.loads(camfile.read_text());report['camera_adjustment_note']='These are the upstream frame0 camera estimates, reported separately. The independent metric applies no additional alignment to recovered motion.'
root_world=world[:,names.index(root)];root_xz=root_world[:,[0,1]]*[1,-1];report['root_world_diagnostics']={'coordinate_system':'Blender Z-up metres; game Y-up via [X,Z,-Y]','first_game_xz_m':root_xz[0].tolist(),'last_game_xz_m':root_xz[-1].tolist(),'end_start_horizontal_distance_m':float(np.linalg.norm(root_world[-1,:2]-root_world[0,:2])),'end_start_world_distance_m':float(np.linalg.norm(root_world[-1]-root_world[0])),'minimum_vertical_m':float(root_world[:,2].min()),'maximum_vertical_m':float(root_world[:,2].max()),'vertical_range_m':float(np.ptp(root_world[:,2])),'note':'Endpoint separation is a diagnostic for a non-looping action, not a requirement to close the loop or a balance test.'}
q_info=np.zeros((len(t),len(names),4));q_info[:,order]=d['quaternions'];qn=q_info/np.linalg.norm(q_info,axis=-1,keepdims=True);dt=np.diff(t);assert(dt>0).all(),'Non-increasing motion times';step=np.degrees(2*np.arccos(np.clip(abs(np.sum(qn[1:]*qn[:-1],axis=-1)),0,1)));k,j=np.unravel_index(np.argmax(step),step.shape);report['temporal_local_rotation_geodesic']={'method':'Quaternion-antipodal shortest-angle difference between adjacent samples; no Euler-wrap jump.','maximum_step_deg':float(step[k,j]),'worst_bone':names[j],'worst_frame':int(k+1),'worst_interval_s':float(dt[k]),'maximum_speed_deg_per_s':float(np.max(step/dt[:,None])),'per_joint_maximum_step_deg':{n:float(step[:,i].max())for i,n in enumerate(names)}}
g=Path(a.gt)if a.gt else P/'ground-truth-native.npz'
if g.exists():
 gt=np.load(g);gtidx=[list(gt['bones']).index(n) for n in names];nearest=np.abs(t[:,None]-gt['times'][None,:]).argmin(1);match=np.abs(t-gt['times'][nearest])<1e-5
 if not match.any():raise ValueError('No exact GT timestamp matches; refusing implicit time alignment')
 truth=gt['heads'][nearest[match]][:,gtidx];gtarm=gt['armature_world'];truth=truth@gtarm[:3,:3].T+gtarm[:3,3];e=np.linalg.norm(world[match]-truth,axis=-1);visible=[j for j,n in enumerate(names) if n!='MOTION'];report['exact_timestamp_matches']=int(match.sum());report['gt_frames']=len(gt['times'])
 def stats(x):return {'mean':float(x.mean()),'rmse':float(np.sqrt(np.mean(x*x))),'p50':float(np.percentile(x,50)),'p95':float(np.percentile(x,95)),'max':float(x.max())}
 report['all_51_joint_world_error_m']=stats(e);report['visible_body_chain_50_joint_world_error_m']=stats(e[:,visible]);report['per_joint_world_error_m']={n:stats(e[:,j]) for j,n in enumerate(names)}
 report['transport_node_note']='MOTION is an invisible ancestor. The fitted LUMBAR root absorbs authored MOTION translation; all51 and visible50 metrics are reported separately.'
 report['root_first_last_error_m']=[float(e[0,names.index(root)]),float(e[-1,names.index(root)])]
 q_info=np.zeros((len(t),len(names),4));q_info[:,order]=d['quaternions'];recrot=Rotation.from_quat(q_info[match][:,:,[1,2,3,0]].reshape(-1,4)).as_matrix().reshape(-1,len(names),3,3);gtrot=gt['basis'][nearest[match]][:,gtidx,:3,:3];gtrot=gtrot/np.linalg.norm(gtrot,axis=-2,keepdims=True);delta=np.swapaxes(gtrot,-1,-2)@recrot;angle=np.degrees(Rotation.from_matrix(delta.reshape(-1,3,3)).magnitude()).reshape(-1,len(names))
 report['all_51_local_rotation_geodesic_deg']=stats(angle);report['visible_body_chain_50_local_rotation_geodesic_deg']=stats(angle[:,visible]);report['per_joint_local_rotation_geodesic_deg']={n:stats(angle[:,j]) for j,n in enumerate(names)}
 assert report['exact_timestamp_matches']==len(t),'Partial-timeline scoring requires explicit review'
assert report['finite']
Path(a.out).parent.mkdir(parents=True,exist_ok=True);Path(a.out).write_text(json.dumps(report,indent=2),encoding='utf8');np.savez_compressed(Path(a.out).with_suffix('.npz'),times=t,bones=np.array(names),world_heads=world,minimum_floor_clearance=np.array(minimum),skin_sample_indices=np.array(sorted(skin_indices)),world_skin_samples=np.array(skin_samples))
print(json.dumps({k:v for k,v in report.items() if not k.startswith('per_joint')},indent=2))
